mapper.select:
SELECT id, user_id, notebook_id, title, content_plain, kind, status, is_favorite, source_url, version, created_at, updated_at, MATCH(title, content_plain) AGAINST (#{keyword} IN NATURAL LANGUAGE MODE) AS score FROM note WHERE user_id = #{userId} AND deleted_at IS NULL AND MATCH(title, content_plain) AGAINST (#{keyword} IN NATURAL LANGUAGE MODE)
AND notebook_id = #{notebookId}
AND status = #{status}
AND is_favorite = #{favorite}
AND id IN
#{nid}
ORDER BY score DESC, updated_at DESC
